<body data-page="service"><?php $nb_active = 'service'; $nb_current = '/brain-tumor-treatment'; include __DIR__ . '/includes/header.php'; ?>

  <main id="main">
    <section class="phero" aria-labelledby="br-title">
      <div class="wrap phero__in">
        <div>
          <ol class="crumbs"><li><a href="/">Home</a></li><li><a href="/#services">Services</a></li><li>Brain Tumor Treatment</li></ol>
          <h1 id="br-title" data-fx="wipe">Brain Tumor Treatment in <span class="grad-text">Bangalore</span></h1>
          <p class="phero__sub" data-fx="fade" style="--d:.15s">A brain tumor is an abnormal growth of cells in the brain or in the tissues around it. Some are benign (not cancer) and grow slowly, while others are malignant and grow fast. Many brain tumors can be removed or well controlled when found early, and the right treatment depends on the exact type.</p>
          <div class="hero__acts" data-fx="fade" style="--d:.25s">
            <a class="btn btn--grad" href="/contact?topic=brain-tumor">Book a consultation<svg class="ic ic--go"><use href="#i-go"/></svg></a>
