          </div>
        </div>
        <div class="phero__pic phero__pic--art" data-fx="iris" style="--d:.15s">
          <img src="/assets/images/illustrations/brain-tumor.svg" alt="Illustration of a brain with a highlighted tumor, representing brain tumor treatment" width="400" height="400" fetchpriority="high">
        </div>
